{
  "findings": [
    {
      "check_id": "CKV_GCP_14",
      "title": "Ensure all Cloud SQL database instance have backup configuration enabled",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "Backup configuration is disabled for the Cloud SQL database instance, which may result in data loss in case of an unexpected failure or deletion."
    },
    {
      "check_id": "CKV_GCP_6",
      "title": "Ensure all Cloud SQL database instance requires all incoming connections to use SSL",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "The Cloud SQL database instance does not require incoming connections to use SSL, making it vulnerable to eavesdropping and man-in-the-middle attacks."
    },
    {
      "check_id": "CKV_GCP_54",
      "title": "Ensure PostgreSQL database 'log_lock_waits' flag is set to 'on'",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "The 'log_lock_waits' flag is set to 'off', which may make it difficult to diagnose performance issues related to lock waits in the PostgreSQL database."
    },
    {
      "check_id": "CKV_GCP_60",
      "title": "Ensure Cloud SQL database does not have public IP",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "The Cloud SQL database instance has a public IP address, making it potentially accessible from the internet and increasing the attack surface."
    }
  ],
  "patched_code": "resource \"google_sql_database_instance\" \"metadata_database\" {\n  name             = \"digital-library-content-management-platform-db-metadata\"\n  database_version = \"POSTGRES_14\"\n  region           = var.region\n  deletion_protection = false\n  settings {\n    tier = \"db-f1-micro\"\n    backup_configuration {\n      enabled = true\n    }\n    ip_configuration {\n      ipv4_enabled    = false\n      require_ssl     = true\n    }\n    database_flags {\n      name  = \"log_lock_waits\"\n      value = \"on\"\n    }\n  }\n}",
  "fix_summary": "Enabled backup configuration, disabled public IP, required SSL for incoming connections, and enabled 'log_lock_waits' flag to improve security and logging for the Cloud SQL database instance."
}
